            <path data-ref="progRef" d="${s._pathD}" fill="none" stroke="url(#ts-grad)" stroke-width="5.5" stroke-linecap="round" stroke-dasharray="0 9999" style="filter:drop-shadow(0 0 7px rgba(240,97,42,.75));"></path>
